func init() {
	raw, err := base64.StdEncoding.DecodeString(biomeParamBlob)
	if err != nil {
		panic("vanilladata: biome parameter blob: " + err.Error())
	}
	const entrySize = 1 + 13*2
	n := len(raw) / entrySize
	BiomeParamAxes = make([][12]int32, n)
	BiomeParamBiome = make([]uint8, n)
	BiomeParamOffset = make([]int32, n)
	for i := 0; i < n; i++ {
		base := i * entrySize
		BiomeParamBiome[i] = raw[base]
		for a := 0; a < 12; a++ {
			BiomeParamAxes[i][a] = int32(int16(binary.LittleEndian.Uint16(raw[base+1+2*a:])))
		}
		BiomeParamOffset[i] = int32(int16(binary.LittleEndian.Uint16(raw[base+1+24:])))
	}
}
